def transform(grid):
    g = np.array(grid)
    bg = background(g)
    out = g.copy()
    H, W = g.shape
    # template: a row fully non-background
    tmpl_y = None
    for y in range(H):
        if np.all(g[y] != bg):
            tmpl_y = y
            break
    if tmpl_y is None:
        emit(out, "No complete template row found; nothing to extend.")
        return out
    tmpl = g[tmpl_y]
    for y in range(H):
        if y == tmpl_y or np.all(g[y] == bg):
            continue
        mapping = {}
        for x in range(W):
            if g[y, x] != bg:
                mapping[int(tmpl[x])] = int(g[y, x])
        for x in range(W):
            c = int(tmpl[x])
            if c in mapping:
                out[y, x] = mapping[c]
        emit(out, f"Row {y}: prefix gives colour map {mapping} from template row {tmpl_y}; "
                  f"rewrote the full row as the template pattern in these colours.")
    emit(out, "All prefix rows extended to follow the template pattern.")
    return out
